//! Golden-value tests for the Lo-MacKinlay variance-ratio test and the
//! Chow-Denning joint test against `fixtures/variance_ratio.json`
//! (generated by `fixtures/generate_variance_ratio_fixtures.py` with
//! arch 8.0.0, scipy 1.18.1, numpy 2.5.3).
//!
//! Tolerances:
//! * `vr` — `1e-12` relative.
//! * `stat` — `|a - e| <= 1e-12 + 1e-10 |e|`: the statistic is
//!   `sqrt(nq) (vr - 1) / sqrt(V)`, and the cancellation in `vr - 1` near 1
//!   amplifies summation-order differences (both sum the variances
//!   sequentially, but arch's robust `theta` uses NumPy's pairwise dot).
//! * `p_value` — against the accurate `2 * norm.sf(|arch stat|)` at `1e-9`
//!   relative with NO absolute floor, so the deep-tail cases
//!   (`|z|` up to 34.6, `p` down to 2.1e-262) really test the `erfc` route;
//!   against arch's own `2 - 2 Phi(|z|)` only at `1e-12` absolute (arch
//!   underflows to 0.0 beyond |z| = 8.3).
//! * `stat_variance` — `1e-10` relative (closed forms; the robust `theta`
//!   carries the same summation-order noise).
//! * `nobs` / `n_dropped` / `lags` — exact.
//! * critical values — `1e-12` relative (AS241 inverse normal vs scipy).

use serde_json::Value;
use tsecon_diag::{
    chow_denning, variance_ratio, variance_ratio_crit, DiagError, VarianceRatioResult,
    VarianceRatioSpec, VrSeType, VrTrend,
};

fn fixture() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/variance_ratio.json"
    );
    let text = std::fs::read_to_string(path).expect("fixture file readable");
    serde_json::from_str(&text).expect("fixture is valid JSON")
}

fn f64s(v: &Value) -> Vec<f64> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|x| x.as_f64().expect("number"))
        .collect()
}

fn usizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|x| x.as_u64().expect("integer") as usize)
        .collect()
}

fn series(fx: &Value, name: &str) -> Vec<f64> {
    f64s(&fx["series"][name])
}

fn rel_close(actual: f64, expected: f64, rtol: f64, ctx: &str) {
    let rel = ((actual - expected) / expected).abs();
    assert!(
        rel <= rtol,
        "{ctx}: actual {actual:e}, expected {expected:e}, rel err {rel:e} > {rtol:e}"
    );
}

fn stat_close(actual: f64, expected: f64, ctx: &str) {
    let tol = 1e-12 + 1e-10 * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{ctx}: stat {actual}, expected {expected}, |diff| {:e} > {tol:e}",
        (actual - expected).abs()
    );
}

fn spec_of(c: &Value) -> VarianceRatioSpec {
    VarianceRatioSpec {
        trend: match c["trend"].as_str().unwrap() {
            "n" => VrTrend::None,
            "c" => VrTrend::Drift,
            other => panic!("unknown trend {other}"),
        },
        overlap: c["overlap"].as_bool().unwrap(),
        debiased: c["debiased"].as_bool().unwrap(),
        robust: c["robust"].as_bool().unwrap(),
    }
}

fn expected_se_type(spec: VarianceRatioSpec) -> VrSeType {
    if !spec.overlap {
        VrSeType::NonOverlapping
    } else if spec.robust {
        VrSeType::Robust
    } else {
        VrSeType::Homoskedastic
    }
}

fn check_one(r: &VarianceRatioResult, c: &Value, i: Option<usize>, ctx: &str) {
    let get = |k: &str| -> f64 {
        match i {
            None => c[k].as_f64().unwrap(),
            Some(i) => c[k][i].as_f64().unwrap(),
        }
    };
    let get_u = |k: &str| -> usize {
        match i {
            None => c[k].as_u64().unwrap() as usize,
            Some(i) => c[k][i].as_u64().unwrap() as usize,
        }
    };
    rel_close(r.vr, get("vr"), 1e-12, &format!("{ctx} vr"));
    stat_close(r.stat, get("stat"), &format!("{ctx} stat"));
    let p_sf = get("pvalue_sf");
    assert!(p_sf > 0.0, "{ctx}: fixture p must be positive");
    rel_close(r.p_value, p_sf, 1e-9, &format!("{ctx} pvalue vs 2*sf"));
    rel_close(
        r.stat_variance,
        get("stat_variance"),
        1e-10,
        &format!("{ctx} stat_variance"),
    );
    assert_eq!(r.nobs, get_u("nobs"), "{ctx} nobs");
    assert_eq!(r.n_dropped, get_u("n_dropped"), "{ctx} n_dropped");
}

#[test]
fn single_horizon_grid_matches_arch() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 250);
    let crit = variance_ratio_crit().unwrap();
    let mut deep_tail = 0;
    for c in cases {
        let name = c["series"].as_str().unwrap();
        let q = c["lags"].as_u64().unwrap() as usize;
        let spec = spec_of(c);
        let ctx = format!(
            "{name} q={q} trend={} ov={} deb={} rob={}",
            c["trend"], spec.overlap, spec.debiased, spec.robust
        );
        let y = series(&fx, name);
        let r = variance_ratio(&y, q, spec).unwrap_or_else(|e| panic!("{ctx}: {e}"));
        check_one(&r, c, None, &ctx);
        assert_eq!(r.lags, q);
        assert_eq!(r.se_type, expected_se_type(spec), "{ctx}");
        assert_eq!(r.debiased, spec.overlap && spec.debiased, "{ctx}");
        // arch's own p-value only to 1e-12 absolute: its 2 - 2 Phi form
        // cancels catastrophically in the tail.
        let p_arch = c["pvalue_arch"].as_f64().unwrap();
        assert!(
            (r.p_value - p_arch).abs() <= 1e-12,
            "{ctx}: p {} vs arch {p_arch}",
            r.p_value
        );
        if p_arch == 0.0 {
            deep_tail += 1;
            assert!(r.p_value > 0.0, "{ctx}: erfc p-value must not underflow");
        }
        // arch's nobs is len(y) before truncation.
        assert_eq!(
            c["arch_nobs"].as_u64().unwrap() as usize,
            y.len(),
            "{ctx} arch_nobs"
        );
        let cv = &c["crit"];
        for (key, val) in [
            ("1%", crit.pct1),
            ("5%", crit.pct5),
            ("10%", crit.pct10),
            ("90%", crit.pct90),
            ("95%", crit.pct95),
            ("99%", crit.pct99),
        ] {
            rel_close(
                val,
                cv[key].as_f64().unwrap(),
                1e-12,
                &format!("{ctx} crit {key}"),
            );
        }
    }
    // The tail series puts real deep-tail cases into the grid.
    assert!(deep_tail >= 20, "only {deep_tail} deep-tail cases");
}

#[test]
fn headline_values_from_the_spec() {
    // Default call (drift, overlap, debiased, robust) on the three headline
    // series; the numbers are arch 8.0.0's, reproduced in the fixture.
    let fx = fixture();
    let rw = variance_ratio(&series(&fx, "rw500"), 4, VarianceRatioSpec::default()).unwrap();
    rel_close(rw.vr, 0.9525033384687233, 1e-12, "rw500 vr");
    stat_close(rw.stat, -0.603632057062107, "rw500 stat");
    let gdp = variance_ratio(&series(&fx, "log_realgdp"), 4, VarianceRatioSpec::default()).unwrap();
    rel_close(gdp.vr, 1.7619906809461274, 1e-12, "gdp vr");
    stat_close(gdp.stat, 4.963205022657067, "gdp stat");
    // The accurate tail, not arch's 6.933931870900523e-07.
    rel_close(gdp.p_value, 6.933931871610465e-07, 1e-9, "gdp p");
    assert!(((gdp.p_value - 6.933931870900523e-07) / gdp.p_value).abs() > 5e-11);
    let ar = variance_ratio(&series(&fx, "ar03_400"), 2, VarianceRatioSpec::default()).unwrap();
    rel_close(ar.vr, 1.2941089675381685, 1e-12, "ar vr");
    stat_close(ar.stat, 5.383992544130618, "ar stat");
    // Trend "n" still debiases (arch applies the nq - 1 correction).
    let y = series(&fx, "rw500");
    let n_deb = variance_ratio(
        &y,
        4,
        VarianceRatioSpec {
            trend: VrTrend::None,
            ..VarianceRatioSpec::default()
        },
    )
    .unwrap();
    let n_raw = variance_ratio(
        &y,
        4,
        VarianceRatioSpec {
            trend: VrTrend::None,
            debiased: false,
            ..VarianceRatioSpec::default()
        },
    )
    .unwrap();
    rel_close(n_deb.vr, 0.9545888741015024, 1e-12, "trend n debiased");
    rel_close(n_raw.vr, 0.9431338998052365, 1e-12, "trend n raw");
}

#[test]
fn chow_denning_matches_the_closed_form() {
    let fx = fixture();
    let cases = fx["chow_denning"].as_array().unwrap();
    assert_eq!(cases.len(), 45);
    for c in cases {
        let name = c["series"].as_str().unwrap();
        let lags = usizes(&c["lags"]);
        let spec = spec_of(c);
        let ctx = format!(
            "CD {name} {lags:?} ov={} deb={} rob={}",
            spec.overlap, spec.debiased, spec.robust
        );
        let r =
            chow_denning(&series(&fx, name), &lags, spec).unwrap_or_else(|e| panic!("{ctx}: {e}"));
        assert_eq!(r.individual.len(), lags.len());
        for (i, ind) in r.individual.iter().enumerate() {
            assert_eq!(ind.lags, lags[i], "{ctx}: order preserved");
            check_one(ind, c, Some(i), &format!("{ctx} [{i}]"));
        }
        stat_close(
            r.stat,
            c["cd_stat"].as_f64().unwrap(),
            &format!("{ctx} cd_stat"),
        );
        assert_eq!(
            r.lag,
            c["cd_lag"].as_u64().unwrap() as usize,
            "{ctx} cd_lag"
        );
        rel_close(
            r.p_value,
            c["cd_pvalue"].as_f64().unwrap(),
            1e-9,
            &format!("{ctx} cd_pvalue"),
        );
        let cc = &c["cd_crit"];
        let crit = [
            (0.01, "1%", r.crit.pct1),
            (0.05, "5%", r.crit.pct5),
            (0.10, "10%", r.crit.pct10),
        ];
        for (alpha, key, val) in crit {
            rel_close(
                val,
                cc[key].as_f64().unwrap(),
                1e-12,
                &format!("{ctx} {key}"),
            );
            // Duality: the p-value and the critical value are the same bound.
            assert_eq!(
                r.p_value < alpha,
                r.stat > val,
                "{ctx}: p {} vs alpha {alpha}, stat {} vs crit {val}",
                r.p_value,
                r.stat
            );
        }
        if lags.len() == 1 {
            assert_eq!(
                r.p_value, r.individual[0].p_value,
                "{ctx}: m = 1 is the single test"
            );
        }
    }
}

#[test]
fn one_q_sum_corners_are_refused_under_both_trends() {
    // arch returns vr = 0.0 (trend "c") or a single-squared-sum ratio
    // (trend "n") on these samples; tsecon refuses all of them by name.
    let fx = fixture();
    let corners = fx["corners"].as_array().unwrap();
    assert_eq!(corners.len(), 8);
    let mut n_trend_nondegenerate = 0;
    for c in corners {
        let y = f64s(&c["y"]);
        let q = c["lags"].as_u64().unwrap() as usize;
        let spec = spec_of(c);
        let arch_vr = c["arch_vr"].as_f64().unwrap();
        if spec.trend == VrTrend::None {
            assert!(arch_vr > 0.0 && arch_vr.is_finite());
            n_trend_nondegenerate += 1;
        } else {
            assert_eq!(arch_vr, 0.0);
        }
        let err = variance_ratio(&y, q, spec).unwrap_err();
        match &err {
            DiagError::InvalidLags {
                nlags, requirement, ..
            } => {
                assert_eq!(*nlags, q);
                assert!(requirement.contains("lags <="), "{requirement}");
                assert!(requirement.contains("two"), "{requirement}");
            }
            other => panic!("expected InvalidLags, got {other:?}"),
        }
    }
    assert_eq!(n_trend_nondegenerate, 4);
}
